const module = angular.module("irtech.netcity.em.statreports", [
	"ngRoute", "ngSanitize", "ngMessages", "ui.select", "uikit.alerts", "uikit.dialogs", "ui.bootstrap",
	"irtech.netcity.common", "ngFileUpload", "ui.tree", "netcity.helpers", "netcity.validation",
	"netcity.indicators.directives", "uikit.controls.controllers", "uikit.controls", "irtech.netcity.ui-components",
	"irtech.netcity.em.statreports.common"
]);

require("approot/global/directives/recursiveDirective.js");
require("approot/global/providers/uikit.controls.coffee");
require("approot/global/providers/netcity.helpers.coffee");
require("approot/global/providers/netcity.validation.coffee");

require("./common/indicatorsRepository.coffee");
require("./common/indicatorViewController.coffee");

require("./index/controller.js");
require("./edit/controllers.coffee");
require("./fill/controller.js");
require("./relevance/controller.coffee");
require("./view/controllers.coffee");

$(() => {
	window.require(["wpt/WebPivotTable", "dojo/domReady!"], (wpt) => {
		window.wpt = wpt;
	});
});


module
	.config(($routeProvider, $locationProvider, $provide) => {
		$routeProvider
			.when("/",
			{
				templateUrl: "/static/dist/app/em/statReports/index/template.html",
				controller: "IndexController"
			})
			.when("/fill/",
			{
				templateUrl: "/static/dist/app/em/statReports/fill/template.html",
				controller: "FillIndicators.View.Em"
			})
			.when("/edit/",
			{
				templateUrl: "/static/dist/app/em/statReports/edit/template.html",
				controller: "Em.Indicators.View"
			})
			.when("/relevance/",
			{
				templateUrl: "/static/dist/app/em/statReports/relevance/template.html",
				controller: "RelevanceData.View"
			})
			.when("/view",
			{
				templateUrl: "/static/dist/app/em/statReports/view/template.html",
				controller: "EmStatReports.View"
			})
			.otherwise({
				redirectTo: "/"
			});

		$provide.decorator('$appLoader', () => {
			return {
				show: () => { },
				hide: () => { }
			}
		});

		$locationProvider.hashPrefix('');
		$locationProvider.html5Mode({
			enabled: true,
			requireBase: true
		});
	})
	.run(($rootScope) => {
		//костыль: добавляем на страницу элемент для отображения данных отчета
		//динамическое создание не работает. видимо ограничение wpt
		//требуется именно один единственный элемент, который создавался один единственный раз
		const wptContainer = $("<div></div>").attr("id", "wpt-container").css({ height: "1000px", width: "1300px" });
		const wptWrap = $("<div></div>").addClass("wpt-styles").append(wptContainer);
		wptWrap.insertAfter($("div[ng-view]"));

		$rootScope.$on("$routeChangeStart",
			() => {
				//прячем элемент перед переходами между экранами
				wptContainer.hide();
			});
	});



