angular
	.module("irtech.netcity.em.statreports")
	.controller("IndexController", ($scope, $http, $location, $appLoader) => {
		$scope.$parent.page = {
			title: language.Generic.StatReports.kStatReports
		}
		$scope.language = language;
		$scope.data = {
			year: null,
			years: []
		}

		$http.get("/webapi/em/years").then((response) => {
			$scope.data.years = response.data;
			$scope.data.year = _.findWhere(response.data, { id: appContext.globalYearId });
			$appLoader.hide();
		});

		$scope.navigate = (url, search) => {
			if (search) {
				$location.path(url).search(search);
			} else {
				$location.path(url);
			}
		}

		$scope.onYearChange = () => {
			const setYearId = $scope.data.year.id;
			$http.post("/webapi/context/year", setYearId).then((response) => { appContext.globalYearId = setYearId; });
		}
	});


