"use strict";

angular
	.module("irtech.netcity.em.statreports")
	.factory("fillIndicatorsRepositoryEm", (indicatorsRepository) => {
		var baseRep = indicatorsRepository.emIndicators.subscribed;
		return {
			get: (indicatorGroupId) => baseRep.get(indicatorGroupId),
			save: (indicatorValues, groupIndicatorId) => baseRep.saveIndicatorValues(indicatorValues, groupIndicatorId),
			approve: (arrIndicatorGroups) => baseRep.approveIndicatorGroups(arrIndicatorGroups),
			getIndicatorGroups: () => baseRep.getGroups(),
			getIndicatorValues: (indicatorGroupId) => baseRep.getIndicatorValues(indicatorGroupId),
			getCalculatedIndicatorValues: (indicatorGroupId) => baseRep.getCalculatedIndicatorValues(indicatorGroupId)
		};
	})
	.controller("FillIndicators.View.Em", ($scope, $alerts, $dialogs, $errorHandler, $collectionHelper, $controller, fillIndicatorsRepositoryEm) => {

		$scope.$parent.page = {
			parent: {
				title: language.Generic.StatReports.kStatReports,
				href: "/angular/em/statreports/"
			},
			back: { history: true },
			title: language.Generic.StatReports.kFillingStatIndicators
		};

		//наследование от базового контроллера
		$controller("FillIndicators.View.Common", { $scope, fillIndicatorsRepository: fillIndicatorsRepositoryEm, $alerts, $dialogs, $errorHandler, $collectionHelper });
	});


